/* ── state update ───────────────────────────────────────────────────────── */
let capLabel = null, activeRow = 0, showScheme = true, mode = 0;
const _A = new THREE.Vector3(), _B = new THREE.Vector3();

function update(t) {
  const dCX = 1.85 + 1.15 * t, dNuC = 3.0 - 1.15 * t;
  let xX = dCX, xNu = -dNuC;
  if (t < 0.12) { const s = t / 0.12; xNu = -(4.2 + (2.862 - 4.2) * s); }
  if (t > 0.88) { const s = (t - 0.88) / 0.12; xX = 2.862 + (4.2 - 2.862) * s; }

  const th = THREE.MathUtils.degToRad(109.5 - 39 * t);
  const st = Math.sin(th), ct = Math.cos(th);
  const hp = [];
  for (let i = 0; i < 3; i++) {
    const phi = THREE.MathUtils.degToRad(90 + 120 * i);
    hp.push(new THREE.Vector3(ct, st * Math.cos(phi), st * Math.sin(phi)).multiplyScalar(1.1));
  }

  cAtom.position.set(0, 0, 0);
  xAtom.position.set(xX, 0, 0);
  nuAtom.position.set(xNu, 0, 0);
  for (let i = 0; i < 3; i++) {
    hAtoms[i].position.copy(hp[i]);
    setBond(bondCH[i], cAtom.position, hp[i], 0.05);
  }
  // C—X
  _A.set(0, 0, 0); _B.set(xX, 0, 0);
  if (xX <= 2.1) { setBond(bondCX, _A, _B, 0.05); hideSegs(segCX); }
  else if (xX <= 3.05) { bondCX.visible = false; setSegBond(segCX, _A, _B, 0.045); }
  else { bondCX.visible = false; hideSegs(segCX); }
  // Nu—C
  _A.set(xNu, 0, 0); _B.set(0, 0, 0);
  const nl = -xNu;
  if (nl <= 2.1) { setBond(bondNuC, _A, _B, 0.05); hideSegs(segNuC); }
  else if (nl <= 3.05) { bondNuC.visible = false; setSegBond(segNuC, _A, _B, 0.045); }
  else { bondNuC.visible = false; hideSegs(segNuC); }

  // metaball blobs + partial charges
  blobs[0].x = 0; blobs[0].y = 0; blobs[0].z = 0;
  for (let i = 0; i < 3; i++) { blobs[1 + i].x = hp[i].x; blobs[1 + i].y = hp[i].y; blobs[1 + i].z = hp[i].z; }
  blobs[4].x = xX; blobs[4].y = 0; blobs[4].z = 0; blobs[4].q = -(0.65 + 0.35 * t);
  blobs[5].x = xNu; blobs[5].y = 0; blobs[5].z = 0; blobs[5].q = -(1.00 - 0.35 * t);
  buildSurface();

  // caption
  let cap = '', cx = 0;
  if (t < 0.25) { cap = 'Tetrahedral'; cx = xX / 2; }
  else if (t > 0.4 && t < 0.6) { cap = 'Planar'; cx = 0; }
  else if (t > 0.75) { cap = 'Tetrahedral'; cx = xNu / 2; }
  if (capLabel) {
    capLabel.div.innerHTML = cap;
    capLabel.div.style.visibility = cap ? 'visible' : 'hidden';
    capLabel.pos.set(cx, -2.62, 0);
  }

  activeRow = t < 0.35 ? 0 : (t <= 0.65 ? 1 : 2);
  applyPanelState();

  const readout = document.getElementById('tRead');
  if (readout) readout.textContent = 't = ' + t.toFixed(2) + ' · ' +
    (activeRow === 0 ? 'Reactants' : activeRow === 1 ? 'Transition state' : 'Products');
}

function applyPanelState() {
  panel.visible = showScheme;
  for (let r = 0; r < 4; r++) {
    const on = (r === 3 || r === activeRow);
    for (const m of rowMats[r]) m.opacity = on ? 1 : 0.20;
  }
  for (const pl of panelLabels) {
    pl.e.div.style.opacity = showScheme ? ((pl.row === 3 || pl.row === activeRow) ? '1' : '0.22') : '0';
  }
}

