  }
  const idx = [];
  const ci = (i, j, k) => vidx[i + CW * (j + CH * k)];
  const quad = (a, b, c, dd, flip) => {
    if (a < 0 || b < 0 || c < 0 || dd < 0) return;
    if (flip) idx.push(a, b, c, a, c, dd); else idx.push(a, dd, c, a, c, b);
  };
  for (let k = 1; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 0; i < NX - 1; i++) {
    const a = field[i + NX * (j + NY * k)] > ISO, b = field[(i + 1) + NX * (j + NY * k)] > ISO;
    if (a === b) continue;
    quad(ci(i, j - 1, k - 1), ci(i, j, k - 1), ci(i, j, k), ci(i, j - 1, k), a);
  }
  for (let k = 1; k < NZ - 1; k++) for (let j = 0; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const a = field[i + NX * (j + NY * k)] > ISO, b = field[i + NX * ((j + 1) + NY * k)] > ISO;
    if (a === b) continue;
    quad(ci(i - 1, j, k - 1), ci(i, j, k - 1), ci(i, j, k), ci(i - 1, j, k), !a);
  }
  for (let k = 0; k < NZ - 1; k++) for (let j = 1; j < NY - 1; j++) for (let i = 1; i < NX - 1; i++) {
    const a = field[i + NX * (j + NY * k)] > ISO, b = field[i + NX * (j + NY * (k + 1))] > ISO;
    if (a === b) continue;
    quad(ci(i - 1, j - 1, k), ci(i, j - 1, k), ci(i, j, k), ci(i - 1, j, k), a);
  }
  const pos = new Float32Array(verts);
  const nv = pos.length / 3;
  const acc = new Float32Array(pos.length), cnt = new Float32Array(nv);
  for (let i = 0; i < idx.length; i += 3) {
    for (let e = 0; e < 3; e++) {
      const a = idx[i + e], b = idx[i + (e + 1) % 3];
      acc[a * 3] += pos[b * 3]; acc[a * 3 + 1] += pos[b * 3 + 1]; acc[a * 3 + 2] += pos[b * 3 + 2]; cnt[a]++;
      acc[b * 3] += pos[a * 3]; acc[b * 3 + 1] += pos[a * 3 + 1]; acc[b * 3 + 2] += pos[a * 3 + 2]; cnt[b]++;
    }
  }
  const F = 0.45;
  for (let i = 0; i < nv; i++) {
    if (!cnt[i]) continue;
    pos[i * 3] += F * (acc[i * 3] / cnt[i] - pos[i * 3]);
    pos[i * 3 + 1] += F * (acc[i * 3 + 1] / cnt[i] - pos[i * 3 + 1]);
    pos[i * 3 + 2] += F * (acc[i * 3 + 2] / cnt[i] - pos[i * 3 + 2]);
  }
  const col = new Float32Array(pos.length);
  for (let i = 0; i < nv; i++) {
    rampColor(charAt(pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2], bl, sep, w), _c1);
    col[i * 3] = _c1.r; col[i * 3 + 1] = _c1.g; col[i * 3 + 2] = _c1.b;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  g.computeBoundingSphere();
  return g;
}

/* ── animated (single-state) group ──────────────────────────────────────── */
const dynGroup = new THREE.Group(); scene.add(dynGroup);
const molDyn = makeMolecule(); dynGroup.add(molDyn.group);
const surfMesh = new THREE.Mesh(new THREE.BufferGeometry(), surfMat);
surfMesh.renderOrder = 3; dynGroup.add(surfMesh);

/* ── 2D reaction-scheme panel (billboarded flat drawing) ────────────────── */
const PANEL_DYN = 8.6, PANEL_FIG = 3.6;
const panel = new THREE.Group(); panel.position.set(PANEL_DYN, 0, 0); scene.add(panel);
const rowY = [2.3, 0, -2.3];
const rowMats = [[], [], [], []];          // index 3 = always-lit (arrows)
const panelLabels = [];
const P = (x, y) => new THREE.Vector3(x, y, 0);

function addLine(row, pts, color, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.075, gapSize: 0.07, transparent: true })
    : new THREE.LineBasicMaterial({ color, transparent: true });
  const l = new THREE.Line(g, m); if (dashed) l.computeLineDistances();
  panel.add(l); rowMats[row].push(m); return l;
}
function addTri(row, ax, ay, bx, by, cx, cy, color) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array([ax, ay, 0, bx, by, 0, cx, cy, 0]), 3));
  const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: true });
  panel.add(new THREE.Mesh(g, m)); rowMats[row].push(m);
}
function addWedge(row, ax, ay, bx, by, hw, color) {
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy);
  const nx = -dy / L * hw, ny = dx / L * hw;
  addTri(row, ax, ay, bx + nx, by + ny, bx - nx, by - ny, color);
}
function addHash(row, ax, ay, bx, by, n, color) {
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy), ux = dx / L, uy = dy / L;
  for (let i = 1; i <= n; i++) {
    const s = i / n, hw = 0.022 + 0.07 * s;
    const px = ax + dx * s, py = ay + dy * s, qx = -uy * hw, qy = ux * hw;
    addLine(row, [P(px - qx, py - qy), P(px + qx, py + qy)], color, false);
  }
}
function addPlus(row, x, y, s, color) {
  addLine(row, [P(x - s, y), P(x + s, y)], color, false);
  addLine(row, [P(x, y - s), P(x, y + s)], color, false);
}
function addDots(row, x, y, color) {
  for (const dy of [0.06, -0.06]) {
    const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: true });
    const c = new THREE.Mesh(new THREE.CircleGeometry(0.038, 12), m);
    c.position.set(x, y + dy, 0); panel.add(c); rowMats[row].push(m);
  }
}
function schemeLabel(row, text, x, y, px, color) {
  const e = addLabel(text, new THREE.Vector3(), { color, fontSize: FS(px) });
  regLabel(e, px);
  panelLabels.push({ e, local: new THREE.Vector3(x, y, 0), row });
  return e;
}
function addArrow(x, yTop, yBot) {
  addLine(3, [P(x, yTop), P(x, yBot + 0.15)], BLACK, false);
  addTri(3, x, yBot, x - 0.08, yBot + 0.18, x + 0.08, yBot + 0.18, BLACK);
}

/* row 0 — reactants:  Nu:–  +  tetrahedral C—X */
{
  const y = rowY[0];
  addDots(0, -1.80, y, MAGENTA);
  addPlus(0, -1.25, y, 0.09, BLACK);
  addLine(0, [P(0.18, y), P(0.95, y)], BLACK, false);
  addWedge(0, -0.05, y + 0.10, -0.52, y + 0.60, 0.085, BLACK);
  addHash(0, 0.06, y + 0.12, 0.34, y + 0.70, 5, BLACK);
  addLine(0, [P(-0.07, y - 0.11), P(-0.52, y - 0.50)], BLACK, false);
  addLine(0, [P(0.04, y - 0.13), P(0.17, y - 0.66)], BLACK, false);
}
/* row 1 — transition state inside brackets */
{
  const y = rowY[1];
  addLine(1, [P(-2.26, y + 0.80), P(-2.44, y + 0.80), P(-2.44, y - 0.80), P(-2.26, y - 0.80)], BLACK, false);
  addLine(1, [P(2.26, y + 0.80), P(2.44, y + 0.80), P(2.44, y - 0.80), P(2.26, y - 0.80)], BLACK, false);
  addLine(1, [P(-1.62, y), P(-0.19, y)], MAGENTA, true);
  addLine(1, [P(0.19, y), P(1.62, y)], MAGENTA, true);
  addWedge(1, -0.04, y + 0.12, -0.22, y + 0.72, 0.075, BLACK);
  addHash(1, 0.06, y + 0.12, 0.27, y + 0.70, 5, BLACK);
  addLine(1, [P(0, y - 0.13), P(0, y - 0.74)], BLACK, false);
}
/* row 2 — products:  Nu—C (wedge & hash reversed)  +  X:– */
{
  const y = rowY[2];
  addLine(2, [P(-0.88, y), P(-0.19, y)], BLACK, false);
  addHash(2, -0.06, y + 0.12, -0.36, y + 0.70, 5, BLACK);
  addWedge(2, 0.05, y + 0.10, 0.52, y + 0.60, 0.085, BLACK);
  addLine(2, [P(-0.05, y - 0.13), P(-0.18, y - 0.66)], BLACK, false);
  addLine(2, [P(0.07, y - 0.11), P(0.52, y - 0.50)], BLACK, false);
  addPlus(2, 1.05, y, 0.09, BLACK);
  addDots(2, 1.82, y, MAGENTA);
}
addArrow(0, rowY[0] - 0.95, rowY[1] + 0.95);
addArrow(0, rowY[1] - 0.95, rowY[2] + 0.95);

/* ── invisible frame boxes: stable camera fit per layout ────────────────── */
const invisMat = new THREE.MeshBasicMaterial({ visible: false });
const frameDyn = new THREE.Mesh(new THREE.BoxGeometry(18.6, 7.2, 5.8), invisMat);
frameDyn.position.set(2.2, -0.05, 0); frameDyn.visible = false; scene.add(frameDyn);
const frameFig = new THREE.Mesh(new THREE.BoxGeometry(12.6, 7.2, 3.2), invisMat);
frameFig.position.set(0.1, -0.05, 0); frameFig.visible = false;

/* ── figure layout (all three states, built lazily) ─────────────────────── */
const FIG_X = -3.25, FIG_SC = 0.55;
let figGroup = null, figBuilt = false;
const figMols = [], figSurf = [], figCaps = [];

function buildFigureLayout() {
  figGroup = new THREE.Group();
  figGroup.position.set(FIG_X, 0, 0);
  const ts = [0, 0.5, 1], ys = [2.35, 0, -2.35], caps = ['Tetrahedral', 'Planar', 'Tetrahedral'];
  for (let i = 0; i < 3; i++) {
    const st = stateAt(ts[i]);
    const bl = blobsFor(st);
    const row = new THREE.Group(); row.position.y = ys[i]; row.scale.setScalar(FIG_SC);
    const inner = new THREE.Group(); inner.position.x = -(st.xNu + st.xX) / 2; row.add(inner);
    const mesh = new THREE.Mesh(buildGeometry(bl, st.sep, st.w), surfMat);
    mesh.renderOrder = 3; inner.add(mesh); figSurf.push(mesh);
    const mol = makeMolecule(); mol.apply(st); inner.add(mol.group); figMols.push(mol);
    figGroup.add(row);
    const cap = addLabel('<b>' + caps[i] + '</b>',
      new THREE.Vector3(FIG_X, ys[i] - 1.30, 0), { color: '#000', fontSize: FS(15) });
    regLabel(cap, 15); figCaps.push(cap);
  }
  figBuilt = true;
}

/* ── dynamic state update ───────────────────────────────────────────────── */
let capLabel = null, activeRow = 0, showScheme = true, mode = 0, layout = 0;

function update(t) {
  const st = stateAt(t);
  molDyn.apply(st);
  const bl = blobsFor(st);
  const g = buildGeometry(bl, st.sep, st.w);
  surfMesh.geometry.dispose();
  surfMesh.geometry = g;

  let cap = '', cx = 0;
  if (t < 0.25) { cap = 'Tetrahedral'; cx = st.xX / 2; }
  else if (t > 0.4 && t < 0.6) { cap = 'Planar'; cx = 0; }
  else if (t > 0.75) { cap = 'Tetrahedral'; cx = st.xNu / 2; }
  if (capLabel) {
    capLabel.div.innerHTML = '<b>' + cap + '</b>';
    capLabel.div.style.visibility = (cap && layout === 0) ? 'visible' : 'hidden';
    capLabel.pos.set(cx, -2.45, 0);
  }

  activeRow = t < 0.35 ? 0 : (t <= 0.65 ? 1 : 2);
  applyPanelState();

  const readout = document.getElementById('tRead');
  if (readout) readout.textContent = 't = ' + t.toFixed(2) + ' · ' +
    (activeRow === 0 ? 'Reactants' : activeRow === 1 ? 'Transition state' : 'Products');
}

function applyPanelState() {
  panel.visible = showScheme;
  for (let r = 0; r < 4; r++) {
    const on = (layout === 1) || r === 3 || r === activeRow;
    for (const m of rowMats[r]) m.opacity = on ? 1.0 : 0.6;
  }
  for (const pl of panelLabels) {
    const on = (layout === 1) || pl.row === 3 || pl.row === activeRow;
    pl.e.div.style.opacity = showScheme ? (on ? '1' : '0.6') : '0';
  }
}

/* ── initial build + camera ─────────────────────────────────────────────── */
update(0);
setCameraView({ projection: 'perspective', azimuthDeg: 85, elevationDeg: 12, rollDeg: 0, heightFraction: 0.86 });

/* ── labels (after camera fit) ──────────────────────────────────────────── */
capLabel = regLabel(addLabel('<b>Tetrahedral</b>', new THREE.Vector3(0.9, -2.45, 0),
  { fontSize: FS(15), color: '#000' }), 15);

// row 0
schemeLabel(0, 'Nu', -2.06, rowY[0], 14, '#E0218A');
schemeLabel(0, '&ndash;', -1.62, rowY[0] + 0.15, 11, '#E0218A');
schemeLabel(0, 'C', 0.0, rowY[0], 14, '#111');
schemeLabel(0, 'X', 1.18, rowY[0], 14, '#E0218A');
// row 1
schemeLabel(1, 'Nu', -1.86, rowY[1], 14, '#E0218A');
schemeLabel(1, '&delta;<sup>&ndash;</sup>', -1.86, rowY[1] + 0.52, 11, '#E0218A');
schemeLabel(1, 'C', 0.0, rowY[1], 14, '#111');
schemeLabel(1, 'X', 1.86, rowY[1], 14, '#E0218A');
schemeLabel(1, '&delta;<sup>&ndash;</sup>', 1.86, rowY[1] + 0.52, 11, '#E0218A');
// row 2
schemeLabel(2, 'Nu', -1.14, rowY[2], 14, '#E0218A');
schemeLabel(2, 'C', 0.0, rowY[2], 14, '#111');
schemeLabel(2, 'X', 1.60, rowY[2], 14, '#E0218A');
schemeLabel(2, '&ndash;', 2.00, rowY[2] + 0.15, 11, '#E0218A');

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(molDyn.nu, {
  title: 'Nucleophile (Nu:⁻)',
  tooltip: 'Nucleophile — attacks from the backside',
  body: 'The electron-rich nucleophile carries the negative charge (pink-red on the map). At the start it is a free ion: its potential surface is a separate round sphere. It attacks carbon 180° away from the leaving group.'
});
registerInteractive(molDyn.x, {
  title: 'Leaving group (X)',
  tooltip: 'Leaving group — takes the electrons with it',
  body: 'As the new Nu–C bond forms, the C–X bond stretches and breaks heterolytically. The negative charge drains onto X, which finally leaves as a separate all-pink X:⁻ sphere.'
});
registerInteractive(molDyn.c, {
  title: 'Carbon undergoing substitution',
  tooltip: 'Carbon: tetrahedral → planar → tetrahedral',
  body: 'At the transition state the three hydrogens are coplanar with carbon and perpendicular to the Nu···C···X axis. Pushing past it turns the umbrella inside out — inversion of configuration.'
});
registerInteractive(surfMesh, {
  title: 'Electrostatic potential map',
  tooltip: 'Electrostatic potential surface',
  body: 'An electron-density envelope coloured by potential: pink/red = most negative, then yellow, green, and a small blue-violet cap over the electron-poor hydrogens. At the transition state both ends are pink (each δ⁻).'
});

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const slider = document.getElementById('reactionProgress');
const btnA = document.getElementById('dmA'), btnB = document.getElementById('dmB'), btnC = document.getElementById('dmC');
const lyA = document.getElementById('lyA'), lyB = document.getElementById('lyB');
const btnScheme = document.getElementById('btnScheme');
const narr = document.getElementById('narr');
let tCur = 0, tTarget = 0, dirty = false;

function setMode(m) {
  mode = m;
  const showSurf = (m !== 2), showMol = (m !== 1);
  surfMesh.visible = showSurf;
  molDyn.group.visible = showMol;
  for (const s of figSurf) s.visible = showSurf;
  for (const o of figMols) o.group.visible = showMol;
  surfMat.opacity = (m === 1) ? 0.92 : 0.55;
  [btnA, btnB, btnC].forEach((b, i) => b.classList.toggle('active', i === m));
}
function setScheme(v) {
  showScheme = v;
  btnScheme.classList.toggle('active', v);
  btnScheme.textContent = (v ? '✓ ' : '') + 'Show 2D reaction scheme';
  applyPanelState();
}
function setLayout(L) {
  layout = L;
  if (L === 1 && !figBuilt) buildFigureLayout();
  if (L === 1) {
    scene.remove(dynGroup); scene.remove(frameDyn);
    scene.add(figGroup); scene.add(frameFig);
    dynGroup.visible = false; figGroup.visible = true;
    panel.position.x = PANEL_FIG;
  } else {
    if (figGroup) { scene.remove(figGroup); scene.remove(frameFig); figGroup.visible = false; }
    scene.add(dynGroup); scene.add(frameDyn);
    dynGroup.visible = true;
    panel.position.x = PANEL_DYN;
  }
  for (const c of figCaps) c.div.style.visibility = (L === 1) ? 'visible' : 'hidden';
  if (capLabel) capLabel.div.style.visibility = (L === 0) ? 'visible' : 'hidden';
  setLabelScale(L === 1 ? 0.60 : 1.0);
  lyA.classList.toggle('active', L === 0);
  lyB.classList.toggle('active', L === 1);
  setMode(mode);
  applyPanelState();
  if (L === 0) update(tCur);
  setCameraView({
    projection: 'perspective', azimuthDeg: 85, elevationDeg: 12, rollDeg: 0,
    heightFraction: L === 1 ? 0.84 : 0.86
  });
}
btnA.onclick = () => setMode(0);
btnB.onclick = () => setMode(1);
btnC.onclick = () => setMode(2);
btnScheme.onclick = () => setScheme(!showScheme);
lyA.onclick = () => setLayout(0);
lyB.onclick = () => setLayout(1);
slider.addEventListener('input', () => {
  stopPlay();
  if (layout !== 0) setLayout(0);
  tCur = tTarget = parseFloat(slider.value);
  dirty = true;
});

/* ── demo steps ─────────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'Reactants', t: 0, mode: 0, scheme: true, layout: 0,
    narr: 'A free nucleophile sits apart as its own isolated pink-red sphere — all the negative charge is on Nu. The alkyl halide is a tetrahedral two-lobed surface whose halide end is also pink-red.'
  },
  {
    title: 'Backside approach', t: 0.30, layout: 0,
    narr: 'Nu moves along the axis exactly opposite X; the two surfaces merge. The C–X bond begins to stretch and the three C–H bonds start to flatten backwards, like an umbrella in the wind.'
  },
  {
    title: 'Planar transition state', t: 0.5, mode: 0, layout: 0,
    narr: 'Carbon is momentarily planar with three coplanar hydrogens; Nu and X are both half-bonded. The surface is a wide symmetric three-lobed shape, pink-red at both ends and green-yellow across the middle — charge is delocalized, each end δ⁻.'
  },
  {
    title: 'Inversion', t: 0.75, layout: 0,
    narr: 'The hydrogens continue through the plane and the new Nu–C bond shortens while C–X keeps stretching. Colour drains from the nucleophile end toward the leaving group.'
  },
  {
    title: 'Products', t: 1, scheme: true, layout: 0,
    narr: 'A tetrahedral product with the substituents turned inside out, beside a separate all-pink halide ion. Compare the wedge and hash in the scheme: they have swapped.'
  },
  {
    title: 'The whole figure', t: 1, scheme: true, layout: 1, mode: 0,
    narr: 'All three states at once, as printed: reactants on top, the planar transition state in the middle, products below — each map beside its wedge/hash structure.'
  },
];
let stepIdx = 0, playTimer = null;

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  if (s.mode !== undefined) setMode(s.mode);
  if (s.scheme !== undefined) setScheme(s.scheme);
  if (s.layout !== undefined && s.layout !== layout) { tCur = tTarget = s.t; setLayout(s.layout); }
  tTarget = s.t;
  narr.innerHTML = '<b>' + s.title + '</b><br>' + s.narr;
}
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  document.getElementById('btnPlay').textContent = '▶ Play';
}
document.getElementById('btnPrev').onclick = () => { stopPlay(); goToStep(stepIdx - 1); };
document.getElementById('btnNext').onclick = () => { stopPlay(); goToStep(stepIdx + 1); };
document.getElementById('btnPlay').onclick = function () {
  if (playTimer) { stopPlay(); return; }
  this.textContent = '❚❚ Pause';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
};
goToStep(0);

/* ── own loop: billboard panel, move its labels, tween t ────────────────── */
function figLoop() {
  requestAnimationFrame(figLoop);
  panel.quaternion.copy(camera.quaternion);
  panel.updateMatrixWorld();
  for (const pl of panelLabels) pl.e.pos.copy(pl.local).applyMatrix4(panel.matrixWorld);

  if (layout === 0) {
    if (Math.abs(tCur - tTarget) > 0.002) { tCur += (tTarget - tCur) * 0.10; dirty = true; }
    else if (tCur !== tTarget) { tCur = tTarget; dirty = true; }
    if (dirty) {
      dirty = false;
      update(tCur);
      slider.value = String(tCur);
    }
  }
}
figLoop();
// @FIGURE_CODE_END

