/* ── reaction state as a pure function of t ─────────────────────────────── */
const BR_C = 1.15, BR_H = 0.95, BR_X = 1.30;     // metaball (Gaussian) radii
const WR_C = 1.50, WR_H = 1.10, WR_X = 2.10;     // charge-weight radii
const Q_C = -0.05, Q_H = 0.46;

function stateAt(t) {
