/* ── scalar fields ──────────────────────────────────────────────────────── */
const ISO = 0.5;
const GR = { x0: -6.6, y0: -2.42, z0: -2.42, step: 0.22 };
const NX = 61, NY = 23, NZ = 23;
const field = new Float32Array(NX * NY * NZ);

function fieldAt(x, y, z, bl) {
  let a = 0;
  for (let i = 0; i < 6; i++) {
    const o = bl[i], dx = x - o.x, dy = y - o.y, dz = z - o.z;
    const d2 = (dx * dx + dy * dy + dz * dz) / (o.r * o.r);
