/* vivid EPM ramp: strong red poles → orange → yellow → green → blue → violet */
const RAMP = [
  [-1.20, new THREE.Color(0xD8403C)],
  [-0.50, new THREE.Color(0xDC4C46)],
  [-0.28, new THREE.Color(0xE85E58)],
  [-0.14, new THREE.Color(0xF0904F)],
  [-0.03, new THREE.Color(0xF2E06B)],
  [0.07, new THREE.Color(0x6FC57A)],
  [0.19, new THREE.Color(0x5E86D8)],
  [0.34, new THREE.Color(0x9C6FD0)],
  [1.30, new THREE.Color(0x9C6FD0)],
];
const _c1 = new THREE.Color();
function rampColor(v, out) {
  if (v <= RAMP[0][0]) { out.copy(RAMP[0][1]); return; }
  for (let i = 1; i < RAMP.length; i++) {
    if (v <= RAMP[i][0]) {
      const a = RAMP[i - 1], b = RAMP[i];
      out.copy(a[1]).lerp(b[1], (v - a[0]) / (b[0] - a[0])); return;
    }
